import React from "react";
import { Link, useNavigate } from "react-router-dom";

const Navbar = ({ loggedIn, setLoggedIn, visitedHome, interviewDone }) => {
  const navigate = useNavigate();

  const handleLogout = () => {
    setLoggedIn(false);
    navigate("/login");
  };

  return (
    <nav className="bg-blue-950 shadow-md py-4 px-8 flex justify-between items-center">
      <Link to="/" className="text-2xl font-bold text-blue-200 hover:text-white transition">
        AI Interview Coach
      </Link>

      <div className="flex gap-6 items-center">
        {loggedIn ? (
          <>
            {/* Home always visible after login */}
            <Link to="/" className="hover:text-blue-300">Home</Link>

            {/* Interview visible only after visiting Home */}
            {visitedHome && (
              <Link to="/interview" className="hover:text-blue-300">Interview</Link>
            )}

            {/* Feedback visible only after completing Interview */}
            {interviewDone && (
              <Link to="/feedback" className="hover:text-blue-300">Feedback</Link>
            )}

            <button
              onClick={handleLogout}
              className="bg-blue-600 px-4 py-2 rounded-md hover:bg-blue-700 transition"
            >
              Logout
            </button>
          </>
        ) : (
          <>
            <Link to="/login" className="hover:text-blue-300">Login</Link>
            <Link to="/signup" className="hover:text-blue-300">Signup</Link>
          </>
        )}
      </div>
    </nav>
  );
};

export default Navbar;
